const Set   = require("#classes/Set.cjs");
var express = require('express');
var router  = express.Router();

/**
* @swagger
* /sets/numSets:
*   get:
*     tags: [Set]
*     summary: Retrieve a num of sets
*     parameters:
*       - in: query
*         name: filter
*         schema:
*           type: integer
*         required: false
*         description: filter values 1 - 5, Other values returns all sets info
*     responses:
*       200:
*         description: A list of users
*         content:
*            application/json:
*              schema:
*               type: object
*               properties:
*                 data:
*                   type: array
*                   example: 
*                       [{"numTotal":950,"numTotalComplete":589,"numTotalCards":103582,"numTotalCardsOwn":59791,"numTotalPendingCards":3}]
*       404:
*         description: Error not found
*       401:
*         description: System error
*/
router.get('/numSets', async function (req, res, next) {
    try {
        setObject   = new Set();
        var message = await setObject.getTotalNumSets(req.query.filter);

        if (message === undefined) {
            res.status(404).send(JSON.stringify({"message": "No data found"}));
        } else {
            res.status(200).json(message);
        }
    } catch (err) {
        res.status(500).json({"message": "System error"});
        next(err);
    }
});

