router.get('/:id', async function (req, res, next) {
    try {
        setObject   = new Set();
        var message = await setObject.getSingleSet(req.params.id);

        if (message === undefined) {
            res.status(404).send(JSON.stringify({"message": "No data found"}));
        } else {
            res.status(200).json(message);
        }
    } catch (err) {
        res.status(500).json({"message": "System error"});
        next(err);
    }
});

/**
* @swagger
* /sets/{id}:
*   put:
*     tags: [Set]
*     summary: Update set data
*     requestBody:
*       required: true
*       content:
*         application/json:
*           schema:
*             type: object
*             properties:
*                onlineSet:
*                  type: integer
*                  default: null
*                complete:
*                  type: integer
*                  default: null
*     parameters:
*       - in: path
*         name: id
*         schema:
*           type: integer
*         required: true
*         description: set ID
*     responses:
*       200:
*         description: Update Set data
*       404:
*         description: Error not found
*       401:
*         description: System error
*/
router.put("/:id", async function (req, res, next) {
    try {
        setObject = new Set();

        if (req.body.onlineSet == null && req.body.complete == null) {
             res.status(401).send({"message": "We need 1 param filled with data"});
            return;
        }

        if (req.body.onlineSet != null && req.body.complete != null) {
            res.status(401).send({"message": "Only 1 param can be filled with values"});
            return;
        }

        if (req.body.onlineSet != null) {
            var message = await setObject.updateSetOnlineSet(req.params.id, req.body);
            if (message === undefined) {
                res.status(401).send({"message": "Error on updating online set"});
                return;
            } else {
                res.status(200).json({message});
                return;
            }
        }

        if (req.body.complete != null) {
            var message = await setObject.updateSetComplete(req.params.id, req.body);
            if (message === undefined) {
                res.status(401).send({"message": "Error on updating complete"});
                return;
            } else {
                res.status(200).json({message});
                return;
            }
        }
    } catch (err) {
        res.status(500).json({"message": "System error"});
        next(err);
    }
});


module.exports = router;
